mapper.select:
/* StdWorkHoursMapper.selectEffectiveRow */
SELECT

  FROM TB_USER_STD_WORK_HOURS H
  LEFT JOIN TB_SYST_VAL_D D
    ON D.SYST_VAL_CD = 'SYS083'
   AND D.SYST_VAL_D_CD = H.REASON_CD
 WHERE H.CMPNY_CD = #{cmpnyCd}
   AND H.USER_CD  = #{userCd}
   AND H.APPLY_STR_DATE  <=  #{baseYmd}
   AND ( H.APPLY_END_DATE IS NULL
         OR H.APPLY_END_DATE  >=  #{baseYmd} )
 ORDER BY H.APPLY_STR_DATE DESC
 LIMIT 1

/* StdWorkHoursMapper.selectHistory */
SELECT

  FROM TB_USER_STD_WORK_HOURS H
  LEFT JOIN TB_SYST_VAL_D D
    ON D.SYST_VAL_CD = 'SYS083'
   AND D.SYST_VAL_D_CD = H.REASON_CD
 WHERE H.CMPNY_CD = #{cmpnyCd}
   AND H.USER_CD  = #{userCd}
 ORDER BY H.APPLY_STR_DATE DESC

/* StdWorkHoursMapper.selectRowByApplyStrDate */
SELECT

  FROM TB_USER_STD_WORK_HOURS H
  LEFT JOIN TB_SYST_VAL_D D
    ON D.SYST_VAL_CD = 'SYS083'
   AND D.SYST_VAL_D_CD = H.REASON_CD
 WHERE H.CMPNY_CD       = #{cmpnyCd}
   AND H.USER_CD        = #{userCd}
   AND H.APPLY_STR_DATE = #{applyStrDate}

/* StdWorkHoursMapper.countOverlap */
SELECT COUNT(1)
  FROM TB_USER_STD_WORK_HOURS H
 WHERE H.CMPNY_CD = #{cmpnyCd}
   AND H.USER_CD  = #{userCd}
   AND NOT ( H.APPLY_END_DATE IS NULL
             AND H.APPLY_STR_DATE  <  #{applyStrDate} )
   AND ( H.APPLY_END_DATE IS NULL
         OR H.APPLY_END_DATE  >=  #{applyStrDate} )

   AND H.APPLY_STR_DATE  <=  #{applyEndDate}


   AND H.APPLY_STR_DATE != #{excludeStrDate}


   AND H.APPLY_STR_DATE != #{excludeStrDate2}

/* StdWorkHoursMapper.selectOpenRowBefore */
SELECT

  FROM TB_USER_STD_WORK_HOURS H
  LEFT JOIN TB_SYST_VAL_D D
    ON D.SYST_VAL_CD = 'SYS083'
   AND D.SYST_VAL_D_CD = H.REASON_CD
 WHERE H.CMPNY_CD = #{cmpnyCd}
   AND H.USER_CD  = #{userCd}
   AND H.APPLY_END_DATE IS NULL
   AND H.APPLY_STR_DATE  <  #{applyStrDate}
 ORDER BY H.APPLY_STR_DATE DESC
 LIMIT 1

mapper.update:
/* StdWorkHoursMapper.closeOpenRowBefore */
UPDATE TB_USER_STD_WORK_HOURS
   SET APPLY_END_DATE = #{closeYmd}
     , UPDATE_NO      = #{updateNo}
     , UPDATE_DATE    = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}
   AND APPLY_END_DATE IS NULL
   AND APPLY_STR_DATE  <  #{applyStrDate}

