/* StdWorkHoursMapper.insertRow */
INSERT INTO TB_USER_STD_WORK_HOURS
    ( CMPNY_CD
    , USER_CD
    , APPLY_STR_DATE
    , APPLY_END_DATE
    , WEEK_STD_MINUTES
    , REASON_CD
    , REASON_DETAIL
    , INSERT_NO
    , INSERT_DATE )
VALUES
    ( #{cmd.cmpnyCd}
    , #{cmd.userCd}
    , #{cmd.applyStrDate}
    , #{cmd.applyEndDate}
    , #{cmd.weekStdMinutes}
    , #{cmd.reasonCd}
    , #{cmd.reasonDetail}
    , #{cmd.actorNo}
    , NOW() )

