/* StdWorkHoursMapper.deleteRow */
DELETE FROM TB_USER_STD_WORK_HOURS
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND USER_CD        = #{userCd}
   AND APPLY_STR_DATE = #{applyStrDate}

mapper.insert:
/* StdWorkHoursMapper.insertMovedRow */
INSERT INTO TB_USER_STD_WORK_HOURS
    ( CMPNY_CD
    , USER_CD
    , APPLY_STR_DATE
    , APPLY_END_DATE
    , WEEK_STD_MINUTES
    , REASON_CD
    , REASON_DETAIL
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE )
VALUES
    ( #{row.cmpnyCd}
    , #{row.userCd}
    , #{row.applyStrDate}
    , #{row.applyEndDate}
    , #{row.weekStdMinutes}
    , #{row.reasonCd}
    , #{row.reasonDetail}
    , #{row.insertNo}
    , COALESCE(STR_TO_DATE(#{row.insertDate}, '%Y-%m-%dT%H:%i:%s'), NOW())
    , #{updateNo}
    , NOW() )

mapper.update:
/* StdWorkHoursMapper.updateRow */
UPDATE TB_USER_STD_WORK_HOURS
   SET APPLY_END_DATE   = #{cmd.applyEndDate}
     , WEEK_STD_MINUTES = #{cmd.weekStdMinutes}
     , REASON_CD        = #{cmd.reasonCd}
     , REASON_DETAIL    = #{cmd.reasonDetail}
     , UPDATE_NO        = #{cmd.actorNo}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD       = #{cmd.cmpnyCd}
   AND USER_CD        = #{cmd.userCd}
   AND APPLY_STR_DATE = #{cmd.applyStrDate}

mapper.select:
/* StdWorkHoursMapper.selectUserEmploymentType */
SELECT COALESCE(U.EMPLOYMENT_TYPE, '') AS employmentType
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN   = 'Y'

/* StdWorkHoursMapper.selectReasonRule */
SELECT

  FROM TB_SYST_VAL_D D
 WHERE D.SYST_VAL_CD   = 'SYS083'
   AND D.SYST_VAL_D_CD = #{reasonCd}
   AND D.USE_YN        = 'Y'
